class Solution:
    def maximumCount(self, nums, queries):
        import heapq
        from collections import defaultdict
        n = len(nums); sz = n - 1
        LIM = 100001
        isp = bytearray([1]) * LIM; isp[0] = isp[1] = 0
        for i in range(2, int(LIM ** 0.5) + 1):
            if isp[i]: isp[i*i::i] = bytearray(len(range(i*i, LIM, i)))
        mx = [0] * (4 * sz); lz = [0] * (4 * sz)
        def upd(o, l, r, ql, qr, v):
            if qr < l or r < ql: return
            if ql <= l and r <= qr:
                mx[o] += v; lz[o] += v; return
            if lz[o]:
                for c in (2*o, 2*o+1):
                    mx[c] += lz[o]; lz[c] += lz[o]
                lz[o] = 0
            m = (l + r) // 2
            upd(2*o, l, m, ql, qr, v); upd(2*o+1, m+1, r, ql, qr, v)
            mx[o] = max(mx[2*o], mx[2*o+1])
        def add(lo, hi, v):
            if lo <= hi: upd(1, 1, sz, lo, hi, v)
        minh = defaultdict(list); maxh = defaultdict(list)
        removed = [False] * n
        for i, x in enumerate(nums):
            heapq.heappush(minh[x], i); heapq.heappush(maxh[x], -i)
        def pmin(v):
            h = minh[v]
            while h and removed[h[0]]: heapq.heappop(h)
            return h[0] if h else None
        def pmax(v):
            h = maxh[v]
            while h and removed[-h[0]]: heapq.heappop(h)
            return -h[0] if h else None
        def contrib(v, s):
            if not isp[v]: return
            mn = pmin(v); mp = pmax(v)
            if mn is not None:
                add(mn + 1, sz, s); add(1, mp, s)
        for v in set(nums): contrib(v, 1)
        ans = []
        for idx, val in queries:
            if val != nums[idx]:
                ov = nums[idx]
                removed[idx] = True; contrib(ov, -1)
                heapq.heappush(minh[val], idx); heapq.heappush(maxh[val], -idx)
                removed[idx] = False; contrib(val, 1)
                nums[idx] = val
            ans.append(mx[1])
        return ans

