class Solution {
public:
    vector<int> maximumCount(vector<int>& nums, vector<vector<int>>& queries) {
        int n = nums.size(), sz = n - 1;
        const int LIM = 100001;
        vector<char> isp(LIM, 1); isp[0] = isp[1] = 0;
        for (int i = 2; i * i < LIM; i++) if (isp[i]) for (int j = i*i; j < LIM; j += i) isp[j] = 0;
        vector<long long> mx(4*sz), lz(4*sz);
        auto upd = [&](auto&& self, int o, int l, int r, int ql, int qr, long long v) -> void {
            if (qr < l || r < ql) return;
            if (ql <= l && r <= qr) { mx[o] += v; lz[o] += v; return; }
            if (lz[o]) { for (int c = 2*o; c <= 2*o+1; c++) { mx[c] += lz[o]; lz[c] += lz[o]; } lz[o] = 0; }
            int m = (l + r) / 2;
            self(self, 2*o, l, m, ql, qr, v); self(self, 2*o+1, m+1, r, ql, qr, v);
            mx[o] = max(mx[2*o], mx[2*o+1]);
        };
        auto add = [&](int lo, int hi, long long v) { if (lo <= hi) upd(upd, 1, 1, sz, lo, hi, v); };
        unordered_map<int, priority_queue<int, vector<int>, greater<int>>> minh;
        unordered_map<int, priority_queue<int>> maxh;
        vector<char> removed(n, 0);
        for (int i = 0; i < n; i++) { minh[nums[i]].push(i); maxh[nums[i]].push(-i); }
        auto pmin = [&](int v) { auto& h = minh[v]; while (!h.empty() && removed[h.top()]) h.pop(); return h.empty() ? INT_MIN : h.top(); };
        auto pmax = [&](int v) { auto& h = maxh[v]; while (!h.empty() && removed[h.top()]) h.pop(); return h.empty() ? INT_MIN : -h.top(); };
        auto contrib = [&](int v, long long s) {
            if (!isp[v]) return;
            int mn = pmin(v), mp = pmax(v);
            if (mn != INT_MIN) { add(mn + 1, sz, s); add(1, mp, s); }
        };
        unordered_set<int> vals(nums.begin(), nums.end());
        for (int v : vals) contrib(v, 1);
        vector<int> ans;
        for (auto& q : queries) {
            int idx = q[0], val = q[1];
            if (val != nums[idx]) {
                int ov = nums[idx];
                removed[idx] = 1; contrib(ov, -1);
                minh[val].push(idx); maxh[val].push(-idx);
                removed[idx] = 0; contrib(val, 1);
                nums[idx] = val;
            }
            ans.push_back((int)mx[1]);
        }
        return ans;
    }
};

