class Solution {
    public int[] maximumCount(int[] nums, int[][] queries) {
        int n = nums.length, sz = n - 1, LIM = 100001;
        boolean[] isp = new boolean[LIM]; Arrays.fill(isp, 2, LIM, true);
        for (int i = 2; i * i < LIM; i++) if (isp[i]) for (int j = i*i; j < LIM; j += i) isp[j] = false;
        long[] mx = new long[4*sz], lz = new long[4*sz];
        class T { void upd(int o, int l, int r, int ql, int qr, long v) {
            if (qr < l || r < ql) return;
            if (ql <= l && r <= qr) { mx[o] += v; lz[o] += v; return; }
            if (lz[o] != 0) { for (int c = 2*o; c <= 2*o+1; c++) { mx[c] += lz[o]; lz[c] += lz[o]; } lz[o] = 0; }
            int m = (l + r) / 2;
            upd(2*o, l, m, ql, qr, v); upd(2*o+1, m+1, r, ql, qr, v);
            mx[o] = Math.max(mx[2*o], mx[2*o+1]);
        }}
        T t = new T();
        java.util.function.BiConsumer<Integer,Integer>[] dummy = null;
        Map<Integer, PriorityQueue<Integer>> minh = new HashMap<>(), maxh = new HashMap<>();
        boolean[] removed = new boolean[n];
        Set<Integer> vals = new HashSet<>();
        for (int i = 0; i < n; i++) {
            minh.computeIfAbsent(nums[i], x -> new PriorityQueue<>()).add(i);
            maxh.computeIfAbsent(nums[i], x -> new PriorityQueue<>(Collections.reverseOrder())).add(-i);
            vals.add(nums[i]);
        }
        int[] tmp = new int[1];
        class H { int pmin(int v) { PriorityQueue<Integer> h = minh.get(v); if (h == null) return Integer.MIN_VALUE; while (!h.isEmpty() && removed[h.peek()]) h.poll(); return h.isEmpty() ? Integer.MIN_VALUE : h.peek(); }
            int pmax(int v) { PriorityQueue<Integer> h = maxh.get(v); if (h == null) return Integer.MIN_VALUE; while (!h.isEmpty() && removed[-h.peek()]) h.poll(); return h.isEmpty() ? Integer.MIN_VALUE : -h.peek(); }
            void contrib(int v, long s) { if (!isp[v]) return; int mn = pmin(v), mp = pmax(v); if (mn != Integer.MIN_VALUE) { if (mn + 1 <= sz) t.upd(1, 1, sz, mn + 1, sz, s); if (1 <= mp) t.upd(1, 1, sz, 1, mp, s); } }
        }
        H h = new H();
        for (int v : vals) h.contrib(v, 1);
        int[] ans = new int[queries.length];
        for (int qi = 0; qi < queries.length; qi++) {
            int idx = queries[qi][0], val = queries[qi][1];
            if (val != nums[idx]) {
                int ov = nums[idx];
                removed[idx] = true; h.contrib(ov, -1);
                minh.computeIfAbsent(val, x -> new PriorityQueue<>()).add(idx);
                maxh.computeIfAbsent(val, x -> new PriorityQueue<>(Collections.reverseOrder())).add(-idx);
                removed[idx] = false; h.contrib(val, 1);
                nums[idx] = val;
            }
            ans[qi] = (int) mx[1];
        }
        return ans;
    }
}

