var maximumCount = function(nums, queries) {
    const n = nums.length, sz = n - 1, LIM = 100001;
    const isp = new Uint8Array(LIM).fill(1); isp[0] = isp[1] = 0;
    for (let i = 2; i * i < LIM; i++) if (isp[i]) for (let j = i*i; j < LIM; j += i) isp[j] = 0;
    const push = (h, x) => { h.push(x); let i = h.length - 1;
        while (i > 0) { const p = (i-1)>>1; if (h[p] <= h[i]) break; [h[p],h[i]]=[h[i],h[p]]; i = p; } };
    const pop = (h) => { const t = h[0], l = h.pop(); if (h.length) { h[0] = l; let i = 0;
        for (;;) { let a = 2*i+1, b = a+1, m = i; if (a < h.length && h[a] < h[m]) m = a; if (b < h.length && h[b] < h[m]) m = b; if (m === i) break; [h[m],h[i]]=[h[i],h[m]]; i = m; } } return t; };
    const mx = new Array(4*sz).fill(0), lz = new Array(4*sz).fill(0);
    function upd(o, l, r, ql, qr, v) {
        if (qr < l || r < ql) return;
        if (ql <= l && r <= qr) { mx[o] += v; lz[o] += v; return; }
        if (lz[o]) { for (const c of [2*o, 2*o+1]) { mx[c] += lz[o]; lz[c] += lz[o]; } lz[o] = 0; }
        const m = (l + r) >> 1;
        upd(2*o, l, m, ql, qr, v); upd(2*o+1, m+1, r, ql, qr, v);
        mx[o] = Math.max(mx[2*o], mx[2*o+1]);
    }
    const add = (lo, hi, v) => { if (lo <= hi) upd(1, 1, sz, lo, hi, v); };
    const minh = new Map(), maxh = new Map();
    const get = (m, k) => { if (!m.has(k)) m.set(k, []); return m.get(k); };
    const removed = new Array(n).fill(false);
    for (let i = 0; i < n; i++) { push(get(minh, nums[i]), i); push(get(maxh, nums[i]), -i); }
    const pmin = (v) => { const h = get(minh, v); while (h.length && removed[h[0]]) pop(h); return h.length ? h[0] : null; };
    const pmax = (v) => { const h = get(maxh, v); while (h.length && removed[-h[0]]) pop(h); return h.length ? -h[0] : null; };
    const contrib = (v, s) => { if (!isp[v]) return; const mn = pmin(v), mp = pmax(v); if (mn !== null) { add(mn+1, sz, s); add(1, mp, s); } };
    for (const v of new Set(nums)) contrib(v, 1);
    const ans = [];
    for (const [idx, val] of queries) {
        if (val !== nums[idx]) {
            const ov = nums[idx];
            removed[idx] = true; contrib(ov, -1);
            push(get(minh, val), idx); push(get(maxh, val), -idx);
            removed[idx] = false; contrib(val, 1);
            nums[idx] = val;
        }
        ans.push(mx[1]);
    }
    return ans;
};
